//! Sections, headers, footers and page fields: reading the corpus files
//! (tests/corpus/docx, generated by scripts/corpus/gen_docx.py), editing
//! them in Kantor and saving.

use std::collections::BTreeMap;
use std::io::{Cursor, Read as _};
use std::path::PathBuf;

use docs_engine::{
    Align, Document, HfKind, HfType, Orientation, PageField, Position, SectionStart, Selection,
    page_field,
};

fn corpus(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/docx")
        .join(name)
}

fn parts(bytes: &[u8]) -> BTreeMap<String, Vec<u8>> {
    let mut zip = zip::ZipArchive::new(Cursor::new(bytes)).unwrap();
    let mut out = BTreeMap::new();
    for i in 0..zip.len() {
        let mut f = zip.by_index(i).unwrap();
        let name = f.name().unwrap().into_owned();
        let mut v = Vec::new();
        f.read_to_end(&mut v).unwrap();
        out.insert(name, v);
    }
    out
}

fn text(p: &BTreeMap<String, Vec<u8>>, name: &str) -> String {
    String::from_utf8(p[name].clone()).unwrap()
}

#[test]
fn report_sections_headers_and_page_fields() {
    let doc = Document::open(&corpus("report.docx")).unwrap();
    assert!(
        !doc.has_unsupported_content(),
        "{:?}",
        doc.unsupported_content()
    );
    let sections = doc.sections();
    assert_eq!(sections.len(), 3, "portrait, landscape, portrait");
    assert_eq!(sections[0].props.page.orientation(), Orientation::Portrait);
    assert_eq!(sections[1].props.page.orientation(), Orientation::Landscape);
    assert_eq!(sections[2].props.page.orientation(), Orientation::Portrait);
    assert_eq!(sections[1].props.start, SectionStart::NextPage);
    assert!(sections[0].props.title_page);
    // python-docx puts the references on the first section; later ones
    // link to it.
    let header = doc
        .story_index_for(&sections, 2, HfKind::Header, HfType::Default)
        .expect("header linked from section 1");
    assert!(
        doc.stories()[header].doc.paragraphs()[0]
            .text
            .contains("Quarterly Operations Report")
    );
    let first = doc
        .story_index_for(&sections, 0, HfKind::Header, HfType::First)
        .unwrap();
    assert_eq!(
        doc.stories()[first].doc.paragraphs()[0].text,
        "CONFIDENTIAL"
    );
    let footer = doc
        .story_index_for(&sections, 0, HfKind::Footer, HfType::Default)
        .unwrap();
    let fp = &doc.stories()[footer].doc.paragraphs()[0];
    let fields: Vec<PageField> = fp.objects().filter_map(|(_, o)| page_field(o)).collect();
    assert_eq!(fields, [PageField::Page, PageField::NumPages]);
    assert_eq!(
        doc.hf_text(0, HfKind::Footer, HfType::Default).0,
        "Page {PAGE} of {PAGES}"
    );
    let numbered =
        docs_engine::with_page_numbers(doc.stories()[footer].doc.paragraphs(), "3", "7").unwrap();
    assert_eq!(numbered[0].text, "Page 3 of 7");
    assert!(
        !doc.preserved_content().iter().any(|p| p.contains("header")),
        "headers are shown now: {:?}",
        doc.preserved_content()
    );
}

#[test]
fn untouched_headers_save_byte_for_byte() {
    let path = corpus("report.docx");
    let orig = parts(&std::fs::read(&path).unwrap());
    let mut doc = Document::open(&path).unwrap();
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("out.docx");
    // A body edit only.
    doc.insert_text(Selection::caret(Position::new(1, 0)), "Edited. ", None);
    doc.save_as(&out).unwrap();
    let saved = parts(&std::fs::read(&out).unwrap());
    for (name, bytes) in &orig {
        if name.contains("header") || name.contains("footer") || name.ends_with("settings.xml") {
            assert_eq!(&saved[name], bytes, "{name} unchanged");
        }
    }
    // The paragraph-level section breaks are kept.
    let body = text(&saved, "word/document.xml");
    assert_eq!(body.matches("<w:sectPr").count(), 3);
    assert!(body.contains("w:orient=\"landscape\""));
}

#[test]
fn edit_footer_and_add_header_round_trip() {
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("new.docx");
    let mut doc = Document::new();
    doc.insert_text(Selection::default(), "Body text", None);
    let sel = Selection::default();
    assert!(doc.set_hf_text(
        0,
        HfKind::Footer,
        HfType::Default,
        "Page {PAGE} of {PAGES}",
        Some(Align::Center),
        sel
    ));
    assert!(doc.set_hf_text(0, HfKind::Header, HfType::Default, "Acme Report", None, sel));
    doc.set_title_page(0, true, sel);
    assert!(doc.set_hf_text(0, HfKind::Header, HfType::First, "Cover", None, sel));
    doc.set_even_odd_headers(true, sel);
    doc.save_as(&out).unwrap();

    let p = parts(&std::fs::read(&out).unwrap());
    let body = text(&p, "word/document.xml");
    assert!(
        body.contains("w:footerReference w:type=\"default\""),
        "{body}"
    );
    assert!(body.contains("w:headerReference w:type=\"first\""));
    assert!(body.contains("<w:titlePg/>"));
    let ct = text(&p, "[Content_Types].xml");
    assert!(ct.contains("wordprocessingml.footer+xml"));
    assert!(ct.contains("wordprocessingml.header+xml"));
    let rels = text(&p, "word/_rels/document.xml.rels");
    assert!(rels.contains("relationships/footer\""));
    let settings = text(&p, "word/settings.xml");
    assert!(settings.contains("<w:evenAndOddHeaders/>"));
    let footer = p
        .iter()
        .find(|(k, _)| k.starts_with("word/footer"))
        .map(|(_, v)| String::from_utf8(v.clone()).unwrap())
        .unwrap();
    assert!(footer.contains("w:instr=\" PAGE"), "{footer}");
    assert!(footer.contains("NUMPAGES"));
    assert!(footer.contains("<w:jc w:val=\"center\"/>"));

    let again = Document::open(&out).unwrap();
    assert!(again.even_odd_headers());
    assert_eq!(
        again.hf_text(0, HfKind::Footer, HfType::Default).0,
        "Page {PAGE} of {PAGES}"
    );
    assert_eq!(again.hf_text(0, HfKind::Header, HfType::First).0, "Cover");
    assert!(again.sections()[0].props.title_page);
}

#[test]
fn header_edits_undo_and_redo() {
    let mut doc = Document::open(&corpus("letter.docx")).unwrap();
    let sel = Selection::default();
    let before = doc.hf_text(0, HfKind::Header, HfType::Default).0;
    assert!(before.contains("Jl. Sudirman"));
    assert!(doc.even_odd_headers());
    assert_eq!(
        doc.hf_text(0, HfKind::Footer, HfType::Even).0,
        "even footer"
    );
    assert!(doc.set_hf_text(
        0,
        HfKind::Header,
        HfType::Default,
        "New letterhead",
        None,
        sel
    ));
    assert!(doc.is_dirty());
    doc.undo();
    assert_eq!(doc.hf_text(0, HfKind::Header, HfType::Default).0, before);
    doc.redo();
    assert_eq!(
        doc.hf_text(0, HfKind::Header, HfType::Default).0,
        "New letterhead"
    );
    // Saving writes only that header part.
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("letter.docx");
    let orig = parts(&std::fs::read(corpus("letter.docx")).unwrap());
    doc.save_as(&out).unwrap();
    let saved = parts(&std::fs::read(&out).unwrap());
    let changed: Vec<&String> = orig
        .keys()
        .filter(|k| saved.get(*k) != orig.get(*k))
        .collect();
    assert_eq!(changed.len(), 2, "document.xml and one header: {changed:?}");
    assert!(changed.iter().any(|k| k.contains("header")));
}

#[test]
fn section_break_and_section_page_setup() {
    let mut doc = Document::new();
    let c = doc.insert_text(Selection::default(), "first part second part", None);
    assert_eq!(doc.sections().len(), 1);
    let at = Selection::caret(Position::new(0, "first part ".len()));
    let after = doc.insert_section_break(at).unwrap();
    assert_eq!(after.head, Position::new(1, 0));
    let s = doc.sections();
    assert_eq!(s.len(), 2);
    assert_eq!(doc.paragraph(0).text, "first part ");
    assert_eq!(doc.paragraph(1).text, "second part");
    // Landscape for the first section only.
    let p = doc.section_page(0).with_orientation(Orientation::Landscape);
    doc.set_section_page(0, p, c);
    assert_eq!(
        doc.sections()[0].props.page.orientation(),
        Orientation::Landscape
    );
    assert_eq!(
        doc.sections()[1].props.page.orientation(),
        Orientation::Portrait
    );
    doc.undo();
    assert_eq!(
        doc.sections()[0].props.page.orientation(),
        Orientation::Portrait
    );
    doc.redo();
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("s.docx");
    doc.save_as(&out).unwrap();
    let again = Document::open(&out).unwrap();
    let s = again.sections();
    assert_eq!(s.len(), 2);
    assert_eq!(s[0].props.page.orientation(), Orientation::Landscape);
    assert_eq!(s[1].props.page.orientation(), Orientation::Portrait);
}

// ── review: tracked changes and comments ────────────────────────────────

#[test]
fn minutes_changes_and_comments_are_read() {
    let doc = Document::open(&corpus("minutes.docx")).unwrap();
    assert!(
        !doc.has_unsupported_content(),
        "{:?}",
        doc.unsupported_content()
    );
    let ch = doc.changes();
    assert_eq!(ch.len(), 2, "{ch:?}");
    assert_eq!(ch[0].kind, docs_engine::RevKind::Insert);
    assert_eq!(ch[0].text, "signed ");
    assert_eq!(ch[0].author, "Citra");
    assert_eq!(ch[1].kind, docs_engine::RevKind::Delete);
    assert_eq!(ch[1].text, " or Monday");
    // Deleted text stays in the text until accepted.
    assert!(
        doc.paragraph(3)
            .text
            .contains("signed draft by Friday or Monday.")
    );
    let cs = doc.comments();
    assert_eq!(cs.len(), 1);
    assert_eq!(cs[0].author, "Ani");
    assert_eq!(cs[0].text, "Check the price clause first.");
    let anchors = doc.comment_anchors();
    assert_eq!(anchors.len(), 1);
    assert_eq!(anchors[0].1.start.para, 2);
}

#[test]
fn untouched_review_content_saves_byte_for_byte() {
    let path = corpus("minutes.docx");
    let orig = parts(&std::fs::read(&path).unwrap());
    let mut doc = Document::open(&path).unwrap();
    doc.insert_text(Selection::caret(Position::new(1, 0)), "Present: ", None);
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("m.docx");
    doc.save_as(&out).unwrap();
    let saved = parts(&std::fs::read(&out).unwrap());
    assert_eq!(saved["word/comments.xml"], orig["word/comments.xml"]);
    let body = text(&saved, "word/document.xml");
    for frag in [
        r#"<w:ins w:id="901" w:author="Citra" w:date="2026-11-10T09:00:00Z"><w:r><w:t xml:space="preserve">signed </w:t></w:r></w:ins>"#,
        r#"<w:del w:id="902" w:author="Citra" w:date="2026-11-10T09:01:00Z"><w:r><w:delText xml:space="preserve"> or Monday</w:delText></w:r></w:del>"#,
        r#"<w:commentRangeStart w:id="0"/>"#,
        r#"<w:commentReference w:id="0"/>"#,
    ] {
        assert!(body.contains(frag), "{frag} missing in {body}");
    }
    let again = Document::open(&out).unwrap();
    assert_eq!(again.changes().len(), 2);
    assert_eq!(again.comments().len(), 1);
}

#[test]
fn accept_and_reject_changes() {
    let mut doc = Document::open(&corpus("minutes.docx")).unwrap();
    // Caret inside "signed ": accept that one.
    let p3 = doc.paragraph(3).text.clone();
    let at = p3.find("signed").unwrap() + 2;
    doc.accept_change(Selection::caret(Position::new(3, at)))
        .unwrap();
    assert_eq!(doc.changes().len(), 1);
    assert!(doc.paragraph(3).text.contains("signed draft"));
    // Reject the deletion: the text stays, unmarked.
    let at = doc.paragraph(3).text.find("or Monday").unwrap();
    doc.reject_change(Selection::caret(Position::new(3, at)))
        .unwrap();
    assert!(doc.changes().is_empty());
    assert_eq!(
        doc.paragraph(3).text,
        "Action: Budi sends the signed draft by Friday or Monday."
    );
    doc.undo();
    doc.undo();
    assert_eq!(doc.changes().len(), 2);
    // Accept all: the deletion goes.
    doc.resolve_all(true, Selection::default());
    assert!(doc.changes().is_empty());
    assert_eq!(
        doc.paragraph(3).text,
        "Action: Budi sends the signed draft by Friday."
    );
    doc.undo();
    // Reject all: the insertion goes.
    doc.resolve_all(false, Selection::default());
    assert_eq!(
        doc.paragraph(3).text,
        "Action: Budi sends the draft by Friday or Monday."
    );
    // Saved without any revision marks.
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("r.docx");
    doc.save_as(&out).unwrap();
    let body = text(&parts(&std::fs::read(&out).unwrap()), "word/document.xml");
    assert!(
        !body.contains("<w:ins ") && !body.contains("<w:del "),
        "{body}"
    );
}

#[test]
fn formatting_and_paragraph_mark_changes_resolve() {
    // A run made bold with tracking on, and an inserted paragraph mark.
    let mut doc = Document::new();
    doc.insert_text(Selection::default(), "one\ntwo", None);
    let bold_change = r#"<w:rPrChange w:id="5" w:author="A" w:date="2026-01-01T00:00:00Z"><w:rPr/></w:rPrChange>"#;
    {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("f.docx");
        doc.save_as(&path).unwrap();
        // Patch the saved body: bold + rPrChange on "one", an inserted mark.
        let mut all = parts(&std::fs::read(&path).unwrap());
        let body = text(&all, "word/document.xml")
            .replacen(
                "<w:p><w:r><w:t xml:space=\"preserve\">one",
                "<w:p><w:pPr><w:rPr><w:ins w:id=\"6\" w:author=\"A\" w:date=\"2026-01-01T00:00:00Z\"/></w:rPr></w:pPr><w:r><w:t xml:space=\"preserve\">one",
                1,
            )
            .replacen(
                "<w:r><w:t xml:space=\"preserve\">one</w:t></w:r>",
                &format!("<w:r><w:rPr><w:b/>{bold_change}</w:rPr><w:t xml:space=\"preserve\">one</w:t></w:r>"),
                1,
            );
        assert!(body.contains("rPrChange"), "{body}");
        all.insert("word/document.xml".into(), body.into_bytes());
        let mut z = zip::ZipWriter::new(Cursor::new(Vec::new()));
        for (k, v) in &all {
            z.start_file(k.as_str(), zip::write::SimpleFileOptions::default())
                .unwrap();
            std::io::Write::write_all(&mut z, v).unwrap();
        }
        std::fs::write(&path, z.finish().unwrap().into_inner()).unwrap();
        doc = Document::open(&path).unwrap();
    }
    assert!(
        !doc.has_unsupported_content(),
        "{:?}",
        doc.unsupported_content()
    );
    assert_eq!(doc.other_changes(), 2);
    let mut rejected = doc.clone();
    // Accept: bold stays, the paragraphs stay apart.
    doc.resolve_all(true, Selection::default());
    assert_eq!(doc.other_changes(), 0);
    assert_eq!(doc.len(), 2);
    assert_eq!(doc.paragraph(0).runs[0].props.bold, Some(true));
    // Reject: not bold, and the inserted mark joins the paragraphs.
    rejected.resolve_all(false, Selection::default());
    assert_eq!(rejected.other_changes(), 0);
    assert_eq!(rejected.len(), 1);
    assert_eq!(rejected.paragraph(0).text, "onetwo");
    assert_ne!(rejected.paragraph(0).runs[0].props.bold, Some(true));
}

#[test]
fn add_edit_and_delete_comments() {
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("c.docx");
    let mut doc = Document::new();
    doc.insert_text(Selection::default(), "Budget approved for Q4.", None);
    let sel = Selection {
        anchor: Position::new(0, 0),
        head: Position::new(0, 6),
    };
    let id = doc
        .add_comment(sel, "Which budget?", "Dewi Lestari")
        .unwrap();
    assert_eq!(doc.comments().len(), 1);
    assert_eq!(doc.comments()[0].initials, "DL");
    let a = doc.comment_anchors();
    assert_eq!(a[0].0, id);
    assert_eq!(a[0].1.start, Position::new(0, 0));
    // The visible text is unchanged (markers are zero-width objects).
    assert_eq!(
        doc.paragraph(0).text.replace(docs_engine::OBJECT, ""),
        "Budget approved for Q4."
    );
    doc.undo();
    assert!(doc.comments().is_empty());
    assert!(doc.comment_anchors().is_empty());
    doc.redo();
    assert_eq!(doc.comments().len(), 1);
    assert!(doc.set_comment_text(&id, "Which budget line?", Selection::default()));
    doc.save_as(&out).unwrap();
    let p = parts(&std::fs::read(&out).unwrap());
    let c = text(&p, "word/comments.xml");
    assert!(c.contains("w:author=\"Dewi Lestari\""), "{c}");
    assert!(c.contains("Which budget line?"));
    assert!(text(&p, "[Content_Types].xml").contains("comments+xml"));
    assert!(text(&p, "word/_rels/document.xml.rels").contains("relationships/comments\""));
    let mut again = Document::open(&out).unwrap();
    assert_eq!(again.comments()[0].text, "Which budget line?");
    assert!(again.delete_comment(&id, Selection::default()));
    assert!(again.comments().is_empty());
    assert!(again.comment_anchors().is_empty());
    assert_eq!(again.paragraph(0).text, "Budget approved for Q4.");
    again.undo();
    assert_eq!(again.comments().len(), 1);
}

#[test]
fn tab_stops_from_paragraph_and_settings() {
    let mut doc = Document::new();
    assert_eq!(doc.default_tab(), 720);
    let mut p = docs_engine::Paragraph::new("Total\tRp 18.000.000");
    p.props.extras.push(
        r#"<w:tabs><w:tab w:val="right" w:leader="dot" w:pos="9026"/><w:tab w:val="left" w:pos="1440"/></w:tabs>"#,
    );
    let stops = doc.tab_stops(&p);
    assert_eq!(
        stops,
        [
            (1440, docs_engine::TabKind::Left),
            (9026, docs_engine::TabKind::Right)
        ]
    );
    // Through a save and a reopen (the element is kept verbatim).
    doc = Document::from_paragraphs(vec![p]);
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("tabs.docx");
    doc.save_as(&out).unwrap();
    let again = Document::open(&out).unwrap();
    assert_eq!(again.tab_stops(again.paragraph(0)).len(), 2);
    assert!(again.default_tab() > 0);
}
